#!/usr/bin/env python3
"""Street Legends backend: Grass enemy-drop item (backend / Publish).

USER SPEC (exact): item name "Grass"; sells for $100 per oz; using it
grants 50% extra health for 1 minute; when collected it goes into the
player's item screen (inventory). Art is embedded as a data URI icon_url (GitHub push cannot carry binary PNGs)
pointing at the repo-root grass-item.png (existing item art uses remote
icon URLs — see the frontend patch report note); the file itself must be
pushed to the repo root as grass-item.png for that URL to resolve. If it
is missing, the item screen falls back to an icon and the item still works.

DEFAULTS (NOT the user's decisions — tune the commented constants):
- Drop: 1 oz of Grass, 25% chance, on enemy defeat — ANY monster kind
  (no kind or level filter), occasional only, never guaranteed. This is
  the implemented rate, flagged as adjustable (change the 0.25 constant).
  PvP and guild-raid victories have no loot path in the snapshot and are
  not hooked by this patch.
- Use: consumes 1 oz; for 60 seconds effective max health is base max
  x 1.5 and current health immediately rises by 50% of base max
  (capped at the boosted max). A second use while active refreshes the
  60s timer (no stacking). When the buff expires, max returns to base
  and current health clamps to base max at the next battle start.
- Sell: $100 per oz, 1 oz per tap, from the item screen.

Design notes (from the snapshot — live /app may differ, hence guards):
- Inventory is player["inventory"], a list of item_id strings or dicts;
  dict entries keep extra keys through migrate_inventory_item, so Grass
  is stored as ONE stacked dict {"item_id": "grass", "qty": N, "unit":
  "oz", ...} rather than one entry per oz.
- Grass is added to ALL_ITEMS so the existing inventory-details endpoint
  returns it (items absent from ALL_ITEMS are invisible on the item
  screen). It is EXCLUDED from the generic random drop pool so the
  dedicated 25% roll stays exactly 25%.
- Buffs live in player["active_buffs"] as {type: "max_health",
  amount, ...}. Grass reuses that system with an expires_at timestamp
  plus a large battles_remaining (10000) so the time expiry — not the
  per-battle decrement — is what ends it. The battle-start max-health
  sum is made expiry-aware (buffs without expires_at are unaffected).
- Combat hook (verified in snapshot): start_battle computes
  buffed_max_health from active_buffs and caps current health to it, so
  an active Grass buff applies to every battle started while it lives.
- The generic sell endpoint pays value//2 and pops one whole entry, so
  it must NOT be used for Grass: dedicated use/sell endpoints below pay
  exactly $100/oz and decrement qty. The frontend hides the generic
  Sell/Equip buttons for Grass rows.
"""
import re, sys
from pathlib import Path

ROOT = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("/app")
SRV = ROOT / "backend/server.py"

GRASS_URL = "data:image/png;base64,"  # embedded art: the GitHub push tool cannot push binary PNGs, so the bag art travels inside this patch as a data URI (falls back to the leaf icon if the client cannot render it)

CATALOG = '''
# GRASS_ITEM_CATALOG: Grass enemy-drop item (see patch header for spec/defaults).
ALL_ITEMS["grass"] = {
    "id": "grass", "name": "Grass", "category": "consumable",
    "description": "Bag of herbs. Use: +50% max health for 60 seconds. Sells for $100 per oz.",
    "icon": "leaf", "icon_url": ''' + '"' + GRASS_URL + '"' + ''',
    "rarity": "common", "equipment_type": "consumable",
    "stats_bonus": {}, "level_requirement": 1, "value": 100,
}
'''

ROUTES = '''
# GRASS_ITEM_USE / GRASS_ITEM_SELL: dedicated Grass endpoints ($100/oz, 1 oz per sell tap).
@api_router.post("/players/{player_id}/grass/use")
async def use_grass(player_id: str):
    """Use 1 oz of Grass: +50% max health for 60 seconds (refreshes if active)."""
    player = await db.players.find_one({"id": player_id})
    if not player:
        raise HTTPException(status_code=404, detail="Player not found")
    inv = player.get("inventory", [])
    g_idx = None
    g_qty = 0
    for _i, _it in enumerate(inv):
        if isinstance(_it, dict) and _it.get("item_id") == "grass":
            g_idx, g_qty = _i, _it.get("qty", 1)
            break
        if isinstance(_it, str) and _it == "grass":
            g_idx, g_qty = _i, 1
            break
    if g_idx is None or g_qty < 1:
        raise HTTPException(status_code=400, detail="No Grass in inventory")
    if g_qty <= 1:
        inv.pop(g_idx)
    elif isinstance(inv[g_idx], dict):
        inv[g_idx]["qty"] = g_qty - 1
    else:
        inv.pop(g_idx)
    stats = player.get("stats", {})
    base_max = stats.get("max_health", 100)
    gain = int(base_max * 0.5)
    boosted_max = base_max + gain
    new_health = min(stats.get("health", base_max) + gain, boosted_max)
    expiry = (datetime.utcnow() + timedelta(minutes=1)).isoformat()
    buffs = [b for b in player.get("active_buffs", []) if b.get("item_id") != "grass"]
    buffs.append({
        "id": "grass_" + str(uuid.uuid4())[:8], "item_id": "grass", "name": "Grass",
        "type": "max_health", "amount": gain, "percent": 0.5,
        "battles_remaining": 10000, "expires_at": expiry, "icon": "leaf",
    })
    await db.players.update_one(
        {"id": player_id},
        {"$set": {"inventory": inv, "active_buffs": buffs, "stats.health": new_health}},
    )
    return {"message": "Grass used! +50% max health for 60 seconds.", "health": new_health,
            "boosted_max_health": boosted_max, "expires_at": expiry, "oz_left": g_qty - 1}


@api_router.post("/players/{player_id}/grass/sell")
async def sell_grass(player_id: str, qty: int = 1):
    """Sell Grass at $100 per oz."""
    if qty < 1:
        raise HTTPException(status_code=400, detail="Quantity must be at least 1")
    player = await db.players.find_one({"id": player_id})
    if not player:
        raise HTTPException(status_code=404, detail="Player not found")
    inv = player.get("inventory", [])
    g_idx = None
    g_qty = 0
    for _i, _it in enumerate(inv):
        if isinstance(_it, dict) and _it.get("item_id") == "grass":
            g_idx, g_qty = _i, _it.get("qty", 1)
            break
        if isinstance(_it, str) and _it == "grass":
            g_idx, g_qty = _i, 1
            break
    if g_idx is None or g_qty < qty:
        raise HTTPException(status_code=400, detail="Not enough Grass in inventory")
    if g_qty <= qty:
        inv.pop(g_idx)
        left = 0
    elif isinstance(inv[g_idx], dict):
        inv[g_idx]["qty"] = g_qty - qty
        left = g_qty - qty
    else:
        inv.pop(g_idx)
        left = 0
    gained = 100 * qty
    await db.players.update_one(
        {"id": player_id},
        {"$set": {"inventory": inv}, "$inc": {"cash": gained}},
    )
    return {"message": f"Sold {qty} oz of Grass for ${gained}", "cash_gained": gained, "oz_left": left}

'''


def main():
    if not SRV.exists():
        print("GRASS_ITEM_ERROR: backend/server.py not found (run from /app)")
        return 1
    src = SRV.read_text(errors="ignore")
    orig = src
    landed = []

    # 1. Catalog entry.
    if "GRASS_ITEM_CATALOG" in src:
        print("GRASS_ITEM_CATALOG_ALREADY_APPLIED"); landed.append("catalog")
    else:
        anchor = "# Apply icon URLs to all equipment items"
        fallback = "ALL_ITEMS.update(LEVEL_ACCESSORIES)"
        if anchor in src:
            src = src.replace(anchor, CATALOG.strip() + "\n\n" + anchor, 1)
            print("GRASS_ITEM_CATALOG_OK"); landed.append("catalog")
        elif fallback in src:
            src = src.replace(fallback, fallback + "\n" + CATALOG.strip(), 1)
            print("GRASS_ITEM_CATALOG_OK"); landed.append("catalog")
        else:
            print("WARNING: catalog anchor not found - Grass NOT added to ALL_ITEMS (item will be invisible on the item screen)")

    # 2. Exclude Grass from the generic random drop pool (keeps the 25% roll exact).
    if 'item["id"] != "grass"' in src:
        print("GRASS_ITEM_POOL_EXCLUDE_ALREADY_APPLIED"); landed.append("pool")
    else:
        old = 'if item["level_requirement"] <= enemy["level"] + 2'
        if old in src:
            src = src.replace(old, 'if item["id"] != "grass" and item["level_requirement"] <= enemy["level"] + 2', 1)
            print("GRASS_ITEM_POOL_EXCLUDE_OK"); landed.append("pool")
        else:
            print("WARNING: generic drop-pool anchor not found - Grass may ALSO drop from the generic pool, so its real drop rate will exceed 25%")

    # 3. Dedicated 25% / 1 oz drop on monster-battle victory.
    if "GRASS_ITEM_DROP" in src:
        print("GRASS_ITEM_DROP_ALREADY_APPLIED"); landed.append("drop")
    else:
        loot_at = src.find('combat_log.append(f"Loot drop: {dropped_item[\'name\']}!")')
        if loot_at == -1:
            print("WARNING: victory loot anchor not found - Grass drop NOT added (no defeat hook)")
        else:
            upd_at = src.find("# Update player stats", loot_at)
            if upd_at == -1:
                print("WARNING: victory update anchor not found - Grass drop NOT added (no defeat hook)")
            else:
                drop = ('            # GRASS_ITEM_DROP: DEFAULT 25% chance, 1 oz, any monster enemy (no kind filter); occasional, never guaranteed.\n'
                        '            if random.random() < 0.25:\n'
                        '                _g_inv = player.get("inventory", [])\n'
                        '                _g_idx = next((i for i, _it in enumerate(_g_inv) if isinstance(_it, dict) and _it.get("item_id") == "grass"), None)\n'
                        '                if _g_idx is None:\n'
                        '                    _g_inv.append({"item_id": "grass", "qty": 1, "unit": "oz", "durability": 100, "max_durability": 100})\n'
                        '                else:\n'
                        '                    _g_inv[_g_idx]["qty"] = _g_inv[_g_idx].get("qty", 1) + 1\n'
                        '                await db.players.update_one({"id": player["id"]}, {"$set": {"inventory": _g_inv}})\n'
                        '                rewards["items"] = (rewards.get("items") or []) + ["grass"]\n'
                        '                combat_log.append("Loot drop: Grass (1 oz)!")\n\n')
                src = src[:upd_at] + drop + src[upd_at:]
                print("GRASS_ITEM_DROP_OK"); landed.append("drop")

    # 4. Inventory-details qty/unit passthrough (item screen needs the oz count).
    if "GRASS_ITEM_QTY" in src:
        print("GRASS_ITEM_QTY_ALREADY_APPLIED"); landed.append("qty")
    else:
        anchor = 'item_with_durability["inventory_index"] = idx'
        if anchor in src:
            add = ('\n            # GRASS_ITEM_QTY: pass stacked quantities through to the item screen.\n'
                   '            if inv_item.get("qty") is not None:\n'
                   '                item_with_durability["qty"] = inv_item["qty"]\n'
                   '            if inv_item.get("unit"):\n'
                   '                item_with_durability["unit"] = inv_item["unit"]')
            src = src.replace(anchor, anchor + add, 1)
            print("GRASS_ITEM_QTY_OK"); landed.append("qty")
        else:
            print("WARNING: inventory-details anchor not found - oz count will NOT reach the item screen (Grass will show without a quantity)")

    # 5. Buff expiry filtering at battle start.
    if "GRASS_ITEM_EXPIRY" in src:
        print("GRASS_ITEM_EXPIRY_ALREADY_APPLIED"); landed.append("expiry")
    else:
        old_hp = 'buff_hp = sum(b["amount"] for b in player.get("active_buffs", []) if b["type"] == "max_health")'
        old_en = 'buff_en = sum(b["amount"] for b in player.get("active_buffs", []) if b["type"] == "max_energy")'
        if old_hp in src and old_en in src:
            new_hp = ('# GRASS_ITEM_EXPIRY: buffs past expires_at no longer count (buffs without expires_at are unaffected).\n'
                      '    _grass_now_iso = datetime.utcnow().isoformat()\n'
                      '    def _grass_buff_live(b):\n'
                      '        _exp = b.get("expires_at")\n'
                      '        return (not _exp) or (str(_exp) >= _grass_now_iso)\n'
                      '    buff_hp = sum(b["amount"] for b in player.get("active_buffs", []) if b["type"] == "max_health" and _grass_buff_live(b))')
            new_en = 'buff_en = sum(b["amount"] for b in player.get("active_buffs", []) if b["type"] == "max_energy" and _grass_buff_live(b))'
            src = src.replace(old_hp, new_hp, 1).replace(old_en, new_en, 1)
            print("GRASS_ITEM_EXPIRY_OK"); landed.append("expiry")
        else:
            print("WARNING: battle-start buff anchor not found - expired Grass buffs would keep counting in battle; COMBAT HOOK NOT VERIFIED, need a live snippet of the start_battle buff calculation")

    # 6. Use + sell endpoints.
    if "GRASS_ITEM_USE" in src and "GRASS_ITEM_SELL" in src:
        print("GRASS_ITEM_ENDPOINTS_ALREADY_APPLIED"); landed.append("endpoints")
    else:
        inc = "app.include_router(api_router)"
        if inc in src and "datetime" in src and "timedelta" in src and "uuid" in src:
            src = src.replace(inc, ROUTES.strip() + "\n\n\n" + inc, 1)
            print("GRASS_ITEM_ENDPOINTS_OK"); landed.append("endpoints")
        else:
            print("WARNING: router anchor or datetime/timedelta/uuid imports not found - Grass use/sell endpoints NOT added")

    if src == orig:
        print("GRASS_ITEM_ALREADY_APPLIED")
        return 0
    try:
        compile(src, "server.py", "exec")
    except SyntaxError as e:
        print("GRASS_ITEM_SYNTAX_FAIL: %s (file NOT written)" % e)
        return 1
    SRV.write_text(src)
    if len(landed) == 6:
        print("GRASS_ITEM_OK")
    else:
        print("GRASS_ITEM_PARTIAL: " + ",".join(landed))
    return 0

if __name__ == "__main__":
    sys.exit(main())
